/**
 *
 * DataTableTFoot is a component that displays a tfoot inside a DataTable.
 *
 * [Live Demo](https://www.primereact.org/datatable/)
 *
 * @module DataTableTFoot
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { DataTableRootInstance } from './DataTableRoot.types';
/**
 * Defines passthrough(pt) options type in DataTableTFoot component.
 */
export type DataTableTFootPassThroughType<E> = PassThroughType<DataTableTFootInstance, E>;
/**
 * Defines passthrough(pt) options of DataTableTFoot component.
 */
export interface DataTableTFootPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: DataTableTFootPassThroughType<React.HTMLAttributes<HTMLTableSectionElement>>;
}
/**
 * Defines valid properties in DataTableTFoot component.
 */
export interface DataTableTFootProps extends BaseComponentProps<DataTableTFootInstance, unknown, DataTableTFootPassThrough, 'tfoot'> {
}
/**
 * Defines valid state in DataTableTFoot component.
 */
export interface DataTableTFootState {
}
/**
 * Defines the methods and properties exposed by DataTableTFoot component.
 */
export interface DataTableTFootExposes {
    /**
     * The DataTable component instance.
     */
    datatable: DataTableRootInstance | undefined | null;
}
/**
 * Instance of DataTableTFoot component.
 */
export type DataTableTFootInstance = ComponentInstance<DataTableTFootProps, DataTableTFootState, DataTableTFootExposes>;
